func javaTools(t *testing.T) (string, string) {
	t.Helper()
	javaHome := os.Getenv("REFINE_JAVA_HOME")
	if javaHome == "" {
		javaHome = os.Getenv("JAVA_HOME")
	}
	if javaHome == "" {
		if _, err := os.Stat("/opt/homebrew/opt/openjdk@25/bin/javac"); err == nil {
			javaHome = "/opt/homebrew/opt/openjdk@25"
		}
	}
	compiler := ""
	if javaHome != "" {
		compiler = filepath.Join(javaHome, "bin", "javac")
	} else {
		compiler, _ = exec.LookPath("javac")
	}
	output, err := exec.Command(compiler, "-version").CombinedOutput()
	major := 0
	fields := strings.Fields(string(output))
	if len(fields) > 1 {
		major, _ = strconv.Atoi(strings.Split(fields[1], ".")[0])
	}
	if err != nil || major < 25 {
		if os.Getenv("REFINE_REQUIRE_JAVA") == "1" {
			t.Fatalf("Java 25 compiler required: %s (%v)", output, err)
		}
		t.Skip("Java 25 compiler unavailable; CI requires it via REFINE_REQUIRE_JAVA=1")
	}
	return compiler, filepath.Join(filepath.Dir(compiler), "java")
}

