func TestGeneratedJavaRuntimeConformance(t *testing.T) {
	compiler, vm := javaTools(t)
	root := t.TempDir()
	files, err := GenerateRuntime("refine.runtime")
	if err != nil {
		t.Fatal(err)
	}
	sources := []string{}
	for _, file := range files {
		target := filepath.Join(root, filepath.FromSlash(file.Path))
		if err := os.MkdirAll(filepath.Dir(target), 0755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(target, []byte(file.Source), 0644); err != nil {
			t.Fatal(err)
		}
		sources = append(sources, target)
	}
	harness := filepath.Join(root, "Conformance.java")
	if err := os.WriteFile(harness, []byte(conformanceJava), 0644); err != nil {
		t.Fatal(err)
	}
	sources = append(sources, harness)
	classes := filepath.Join(root, "classes")
	args := append([]string{"--release", "25", "-encoding", "UTF-8", "-Xlint:all", "-Werror", "-d", classes}, sources...)
	if output, err := exec.Command(compiler, args...).CombinedOutput(); err != nil {
		t.Fatalf("javac: %v\n%s", err, output)
	}
	vectors := conformanceVectors(t)
	var input strings.Builder
	for _, v := range vectors {
		input.WriteString(v.input)
		input.WriteByte('\n')
	}
	command := exec.Command(vm, "-cp", classes, "Conformance")
	command.Stdin = strings.NewReader(input.String())
	var stderr bytes.Buffer
	command.Stderr = &stderr
	output, err := command.Output()
	if err != nil {
		t.Fatalf("Java conformance: %v\n%s", err, stderr.String())
	}
	lines := strings.Split(strings.TrimSuffix(string(output), "\n"), "\n")
	if len(lines) != len(vectors) {
		t.Fatalf("Java returned %d results, expected %d; stderr=%s", len(lines), len(vectors), stderr.String())
	}
	for i, v := range vectors {
		if lines[i] != v.expected {
			t.Fatalf("vector %d: %s\nJava: %s\nGo: %s", i, v.input, lines[i], v.expected)
		}
	}
	t.Logf("%d cross-runtime vectors passed", len(vectors))
}

